package server

import "github.com/Autumn-27/artex/config"

// Catalog that translates user-facing backend messages into the active output
// language. The writeErr response strings and some writeJSON error fields in this
// repository are written as English constants/literals (F3b/F34). The English
// originals are the keys and the Korean, Chinese, Spanish, and Japanese translations
// are the values. English (en) is the key itself, so it is not stored; on lookup
// failure or when en is active, the original is returned unchanged.
//
// Keys are generated by extracting them byte-for-byte from the English
// constants/literals in the source (with a script). Because they are not typed by
// hand, runtime values passed to writeErr can never drift from the keys and be
// silently dropped.
//
// For format-string constants (%d, %s, %w, etc.), the formatted result differs from
// the key, so callers must first translate the template itself with trMsg(template)
// before passing it to fmt.Sprintf/fmt.Errorf.

// trMsg translates an English source message into the active output language. If it
// is missing from the catalog or the active language is English, the original is
// returned unchanged. config.ActiveLanguage reflects the runtime setting (settings
// table), so the user's chosen language takes effect immediately.
func trMsg(ko string) string {
	if m, ok := errCatalog[ko]; ok {
		if v, ok2 := m[config.ActiveLanguage()]; ok2 && v != "" {
			return v
		}
	}
	return ko
}

// logT translates an operator-facing console log template (config.T) so server
// log.Printf sites can wrap a template without each file importing config.
func logT(ko string) string { return config.T(ko) }

// loadOutputLanguage resolves the user-facing output language from the source of
// truth: the runtime setting (settings table) over config.Language() (ARTEX_LANG >
// config file > ko). Call it only to (re)fill the cache; it does a DB query and a
// config file read.
func (s *Server) loadOutputLanguage() string {
	if s.m != nil && s.m.pg != nil {
		if v, ok, _ := s.m.pg.GetSetting(settingOutputLanguage); ok {
			if nv := config.NormalizeLanguage(v); nv != "" {
				return nv
			}
		}
	}
	return config.Language()
}

// outputLanguage returns the cached output language, resolving it on first use.
func (s *Server) outputLanguage() string {
	if v, ok := s.outputLang.Load().(string); ok && v != "" {
		return v
	}
	v := s.loadOutputLanguage()
	s.outputLang.Store(v)
	return v
}
